-- Real-life practice database for the free MySQL course: Marketplace (2,000 orders).
-- 5 related tables, 24 columns, generated from a fixed seed so
-- it matches the in-browser code arena row for row. All data is fictional.
-- MySQL 8.0.16+ (8.4 recommended). Safe to re-run: no DROP, INSERT IGNORE.
-- Workbench: File > Open SQL Script > Execute.  CLI: mysql -u USER -p < mysql-reallife-ecommerce.sql
CREATE DATABASE IF NOT EXISTS portfolio_ecommerce CHARACTER SET utf8mb4;
USE portfolio_ecommerce;

CREATE TABLE IF NOT EXISTS sellers (
 seller_id INT PRIMARY KEY,
 seller_name VARCHAR(80) NOT NULL,
 city VARCHAR(60) NOT NULL,
 rating DECIMAL(3,2) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (
 product_id INT PRIMARY KEY,
 seller_id INT NOT NULL,
 product_name VARCHAR(80) NOT NULL,
 category VARCHAR(40) NOT NULL,
 price DECIMAL(10,2) NOT NULL,
 stock INT NOT NULL,
 FOREIGN KEY (seller_id) REFERENCES sellers(seller_id),
 CHECK (price >= 0)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (
 customer_id INT PRIMARY KEY,
 customer_name VARCHAR(80) NOT NULL,
 city VARCHAR(60) NOT NULL,
 signup_date DATE NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (
 order_id INT PRIMARY KEY,
 customer_id INT NOT NULL,
 order_date DATE NOT NULL,
 status VARCHAR(20) NOT NULL,
 payment_mode VARCHAR(20) NOT NULL,
 FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
 CHECK (status IN ('delivered','shipped','cancelled','returned'))
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (
 order_id INT NOT NULL,
 product_id INT NOT NULL,
 quantity INT NOT NULL,
 unit_price DECIMAL(10,2) NOT NULL,
 discount INT NOT NULL,
 PRIMARY KEY (order_id, product_id),
 FOREIGN KEY (order_id) REFERENCES orders(order_id),
 FOREIGN KEY (product_id) REFERENCES products(product_id),
 CHECK (quantity > 0)
) ENGINE=InnoDB;

